let session,ort;
async function initialize(){if(session)return;ort=await import('./vendor/ort.wasm.min.mjs');ort.env.wasm.numThreads=1;ort.env.wasm.proxy=false;ort.env.wasm.wasmPaths={mjs:new URL('./vendor/ort-wasm-simd-threaded.mjs',import.meta.url).href,wasm:new URL('./vendor/ort-wasm-simd-threaded.wasm',import.meta.url).href};ort.env.logLevel='warning';self.postMessage({phase:'download'});session=await ort.InferenceSession.create(new URL('./vendor/u2netp.onnx',import.meta.url).href,{executionProviders:['wasm'],graphOptimizationLevel:'all'});}
self.onmessage=async({data})=>{try{await initialize();self.postMessage({phase:'inference'});const pixels=data.pixels,n=320*320,values=new Float32Array(n*3),mean=[.485,.456,.406],std=[.229,.224,.225];let max=1;for(let i=0;i<pixels.length;i+=4)max=Math.max(max,pixels[i],pixels[i+1],pixels[i+2]);for(let i=0;i<n;i++)for(let c=0;c<3;c++)values[c*n+i]=(pixels[i*4+c]/max-mean[c])/std[c];const result=await session.run({[session.inputNames[0]]:new ort.Tensor('float32',values,[1,3,320,320])});const raw=result[session.outputNames[0]].data;let lo=Infinity,hi=-Infinity;for(let v of raw){lo=Math.min(lo,v);hi=Math.max(hi,v)}let alpha=new Uint8Array(n),l=320,t=320,r=0,b=0;for(let i=0;i<n;i++){alpha[i]=Math.round(Math.min(1,Math.max(0,(raw[i]-lo)/Math.max(1e-6,hi-lo)))*255);if(alpha[i]>110){let x=i%320,y=Math.floor(i/320);l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y)}}const bounds=r>l?[l/320,t/320,(r-l+1)/320,(b-t+1)/320]:[.15,.1,.7,.8];self.postMessage({id:data.id,alpha,bounds},[alpha.buffer]);}catch(e){self.postMessage({id:data.id,error:e.message??String(e)})}};
